import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] g;
    static int[][] up;
    static int[] depth;
    static int[] parent;
    static int LOG;

    // 普通 LCA
    static int lca(int u, int v) {
        if (depth[u] < depth[v]) {
            int temp = u;
            u = v;
            v = temp;
        }

        // 先把 u 提到和 v 同一深度
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) {
            if (((diff >> k) & 1) == 1) {
                u = up[k][u];
            }
        }

        if (u == v) {
            return u;
        }

        // 一起向上跳
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][u] != up[k][v]) {
                u = up[k][u];
                v = up[k][v];
            }
        }

        return up[0][u];
    }

    // 求解功能写在外部函数里
    static void solve(BufferedReader br) throws Exception {
        int T = Integer.parseInt(br.readLine());

        while (T-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int q = Integer.parseInt(st.nextToken());

            LOG = 20;
            g = new ArrayList[n + 1];
            for (int i = 1; i <= n; i++) {
                g[i] = new ArrayList<>();
            }

            // 建树
            for (int i = 0; i < n - 1; i++) {
                st = new StringTokenizer(br.readLine());
                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());
                g[x].add(y);
                g[y].add(x);
            }

            up = new int[LOG][n + 1];
            depth = new int[n + 1];
            parent = new int[n + 1];

            // 用栈模拟 DFS，避免递归过深
            int[] stack = new int[n];
            int top = 0;
            stack[top++] = 1;
            parent[1] = 0;

            while (top > 0) {
                int u = stack[--top];
                for (int v : g[u]) {
                    if (v == parent[u]) {
                        continue;
                    }
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack[top++] = v;
                }
            }

            // 初始化第 0 层祖先
            for (int i = 1; i <= n; i++) {
                up[0][i] = parent[i];
            }

            // 倍增预处理
            for (int k = 1; k < LOG; k++) {
                for (int i = 1; i <= n; i++) {
                    up[k][i] = up[k - 1][up[k - 1][i]];
                }
            }

            StringBuilder sb = new StringBuilder();

            for (int i = 0; i < q; i++) {
                st = new StringTokenizer(br.readLine());
                int r = Integer.parseInt(st.nextToken());
                int u = Integer.parseInt(st.nextToken());
                int v = Integer.parseInt(st.nextToken());

                int a = lca(u, v);
                int b = lca(u, r);
                int c = lca(v, r);

                // 按结论分类讨论
                if (a == b) {
                    sb.append(c).append('\n');
                } else if (a == c) {
                    sb.append(b).append('\n');
                } else {
                    sb.append(a).append('\n');
                }
            }

            System.out.print(sb.toString());
        }
    }

    // 输入输出写在主函数里
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        solve(br);
    }
}
